#: Arabic greetings (matched on the whole normalised question, like the English GREETING_PATTERN).
GREETINGS: Tuple[str, ...] = ("مرحبا", "مرحباً", "مرحبًا", "اهلا", "اهلاً", "اهلا وسهلا", "اهلا بك", "اهلا بكم", "السلام عليكم", "السلام عليكم ورحمة الله", "السلام عليكم ورحمة الله وبركاته",
                              "سلام", "سلام عليكم", "صباح الخير", "مساء الخير", "صباح النور", "مساء النور", "هاي", "هلا", "هلا والله", "يا هلا", "تحية طيبة", "تحياتي", "مرحبتين", "اهلين", "هلو")


def _article_free(token: str) -> str:
    """The token without a plain definite article (``ال``); clitic prefixes stay, they change the meaning."""
    return token[2:] if token.startswith("\u0627\u0644") and len(token) >= 4 else token


def _split_forms(spec: str) -> List[str]:
    return [f.strip() for f in spec.split("|") if f.strip()]


def build_index() -> Dict[Tuple[str, ...], Tuple[str, str]]:
    """``{normalised Arabic form as a tuple of tokens: (english, flags)}``. Built from ENTRIES by ``arabic_query``; the
    first entry that declares a form wins, so put specific phrases before generic words."""
    from .arabic_text import normalize_arabic, strip_article

    index: Dict[Tuple[str, ...], Tuple[str, str]] = {}
    for spec, english, flags in ENTRIES:
        for form in _split_forms(spec):
            tokens = tuple(_article_free(t) for t in normalize_arabic(form).split())
            if tokens and tokens not in index:
                index[tokens] = (english, flags)
    return index


__all__ = ["ENTRIES", "GREETINGS", "build_index"]
